import cgi
import http.server
import smtplib
from email.mime.text import MIMEText
import json

class EmailHandler(http.server.BaseHTTPRequestHandler):
    def __init__(self, *args, smtp_server=None, smtp_port=None, smtp_username=None, smtp_password=None, **kwargs):
        self.smtp_server = smtp_server
        self.smtp_port = smtp_port
        self.smtp_username = smtp_username
        self.smtp_password = smtp_password
        super().__init__(*args, **kwargs)

    def _send_email(self, subject, message, to):
        msg = MIMEText(message)
        msg['Subject'] = subject
        msg['From'] = self.smtp_username
        msg['To'] = to

        with smtplib.SMTP(self.smtp_server, self.smtp_port) as server:
            server.starttls()
            server.login(self.smtp_username, self.smtp_password)
            server.sendmail(self.smtp_username, [to], msg.as_string())

    def do_POST(self):
        try:
            content_type, _ = cgi.parse_header(self.headers.get('Content-Type', ''))
            if content_type == 'application/json':
                content_length = int(self.headers.get('Content-Length', 0))
                body = self.rfile.read(content_length)
                data = json.loads(body.decode('utf-8'))

                if not all(key in data for key in ['subject', 'message', 'to']):
                    raise ValueError("Missing required keys in JSON")

                self._send_email(data['subject'], data['message'], data['to'])
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps({"status": "Email sent successfully"}).encode('utf-8'))
            else:
                self.send_error(415, "Unsupported Media Type")
        except json.JSONDecodeError:
            self.send_error(400, "Invalid JSON")
        except ValueError as e:
            self.send_error(400, str(e))
        except smtplib.SMTPAuthenticationError:
            self.send_error(535, "Authentication Failed")
        except Exception as e:
            self.send_error(500, str(e))

