    df = pd.DataFrame(dictionary)

    # Find positions of the item in the DataFrame
    positions = []
    for col in df.columns:
        for idx, value in df[col].items():
            if value == item:
                positions.append((idx, col))

    # Set random seed if provided
    if random_seed is not None:
        seed(random_seed)

    # Return random sample if sample_size is specified
    if sample_size is not None and sample_size < len(positions):
        sampled_positions = sample(positions, sample_size)
